questions.solution:
function tokenize(source) {
  const tokens = [];
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    const start = i;
    if (ch === " ") {
      i++;
    } else if (/[0-9]/.test(ch)) {
      while (i < source.length && /[0-9]/.test(source[i])) i++;
      tokens.push({ type: "number", value: Number(source.slice(start, i)) });
    } else if (/[a-z]/.test(ch)) {
      while (i < source.length && /[a-z]/.test(source[i])) i++;
      const name = source.slice(start, i);
      if (name !== "price" && name !== "qty") throw new SyntaxError(`unknown name "${name}" at position ${start}`);
      tokens.push({ type: "name", value: name });
    } else if ("+-*/()".includes(ch)) {
      tokens.push({ type: "op", value: ch });
      i++;
    } else {
      throw new SyntaxError(`unexpected "${ch}" at position ${start}`);
    }
  }
  return tokens;
}

console.log(tokenize("(price - 500) * qty").map((t) => t.value).join(" | "));
try {
  tokenize("price % 2");
} catch (error) {
  console.log(`${error.name}: ${error.message}`);
}

