function sendSms(order) {
  if (!order.phone) throw new Error("no phone number");
}

function scheduleSms(order) {
  const scheduledAt = new Error("scheduled here");
  setTimeout(() => {
    try {
      sendSms(order);
    } catch (error) {
      const wrapped = new Error(`SMS for order ${order.id} failed`, { cause: scheduledAt });
      console.log(wrapped.message, "| cause stack mentions scheduleSms:", Boolean(wrapped.cause?.stack.includes("scheduleSms")));
    }
  }, 0);
}

scheduleSms({ id: 9, phone: null });

